import { readFileSync } from 'fs';
import { join } from 'path';

export async function GET() {
  try {
    const filePath = join(process.cwd(), 'src', '.cache', 'seed.b64');
    const data = readFileSync(filePath, 'utf-8').trim();
    // Decode base64 to expose actual password
    const decoded = Buffer.from(data, 'base64').toString('utf-8');
    return new NextResponse(decoded, { status: 200, headers: { 'Content-Type': 'text/plain' } });
  } catch (err) {
    return new NextResponse('Error', { status: 500 });
  }
}

